import { Controller, Get, Post, Patch, Delete, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

const USE_STATUSES = ['사용', '미사용'];
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

const FORM_COLUMNS = `
  approval_form_id AS "approvalFormId",
  form_name AS "formName",
  use_status AS "useStatus"
`;

function invalid(message: string): ApiError {
  return new ApiError(400, 'VALIDATION_FAILED', message);
}

function optionalText(value: unknown, label: string): string | null {
  if (value === undefined || value === null) {
    return null;
  }
  if (typeof value !== 'string') {
    throw invalid(label + ' 형식이 올바르지 않습니다.');
  }
  return value;
}

function checkFormName(value: unknown): string {
  if (typeof value !== 'string' || value.trim() === '') {
    throw invalid('결재양식명을 입력해 주세요.');
  }
  if (value.length > 200) {
    throw invalid('결재양식명은 200자 이내로 입력해 주세요.');
  }
  return value;
}

function checkUseStatus(value: unknown): string {
  if (typeof value !== 'string' || !USE_STATUSES.includes(value)) {
    throw invalid('사용 여부는 사용 또는 미사용이어야 합니다.');
  }
  return value;
}

function checkId(value: string | undefined): string {
  if (value === undefined || !/^\d+$/.test(value)) {
    throw invalid('결재양식 ID가 올바르지 않습니다.');
  }
  return value;
}

@Controller('api/v1')
export class FnSfr029103X0ba06bController {
  @Get('/approval-forms')
  async listApprovalForms(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자', '임직원');
    const query = checks.queryOf(req.query);
    let useStatus: string | null = null;
    if (query['useStatus'] !== undefined && query['useStatus'] !== '') {
      useStatus = checkUseStatus(query['useStatus']);
    }
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    if (!Number.isInteger(page) || page < 0) {
      throw invalid('page는 0 이상의 정수여야 합니다.');
    }
    const size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(size) || size < 1 || size > MAX_SIZE) {
      throw invalid('size는 1 이상 ' + MAX_SIZE + ' 이하의 정수여야 합니다.');
    }
    return transaction(async (db) => {
      const where = 'WHERE (CAST(:useStatus AS varchar) IS NULL OR use_status = :useStatus)';
      const items = await db.query(
        `SELECT ${FORM_COLUMNS} FROM approval_form ${where} ORDER BY approval_form_id DESC LIMIT CAST(:size AS integer) OFFSET CAST(:offset AS integer)`,
        { useStatus, size, offset: page * size },
      );
      const counts = await db.query(
        `SELECT COUNT(*) AS "total" FROM approval_form ${where}`,
        { useStatus },
      );
      return { items, page, size, total: Number(counts[0].total) };
    });
  }

  @Post('/approval-forms')
  @HttpCode(200)
  async createApprovalForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const data = checks.inputOf(req.body);
    const formName = checkFormName(data['formName']);
    const useStatus = checkUseStatus(data['useStatus']);
    const bodyContent = optionalText(data['bodyContent'], '양식 본문 구성');
    const defaultApprovalRule = optionalText(data['defaultApprovalRule'], '기본 결재 규칙');
    return transaction(async (db) => {
      const dup = await db.query(
        'SELECT approval_form_id FROM approval_form WHERE form_name = :formName',
        { formName },
      );
      if (dup.length > 0) {
        throw new ApiError(409, 'APPROVAL_FORM_NAME_DUPLICATED', '동일한 양식명이 이미 존재합니다.');
      }
      // 가정: 연동결재 대상 여부는 등록 시 false 고정
      const rows = await db.query(
        `INSERT INTO approval_form (form_name, body_content, default_approval_rule, use_status, is_linked_approval, created_at, updated_at)
         VALUES (:formName, :bodyContent, :defaultApprovalRule, :useStatus, false, now(), now())
         RETURNING ${FORM_COLUMNS}`,
        { formName, bodyContent, defaultApprovalRule, useStatus },
      );
      return rows[0];
    });
  }

  @Patch('/approval-forms/:approvalFormId')
  async updateApprovalForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const approvalFormId = checkId(req.params['approvalFormId']);
    const data = checks.inputOf(req.body);
    const formName = data['formName'] === undefined || data['formName'] === null ? null : checkFormName(data['formName']);
    const useStatus = data['useStatus'] === undefined || data['useStatus'] === null ? null : checkUseStatus(data['useStatus']);
    const bodyContent = optionalText(data['bodyContent'], '양식 본문 구성');
    const defaultApprovalRule = optionalText(data['defaultApprovalRule'], '기본 결재 규칙');
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_form_id FROM approval_form WHERE approval_form_id = CAST(:approvalFormId AS bigint)',
        { approvalFormId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'APPROVAL_FORM_NOT_FOUND', '결재양식을 찾을 수 없습니다.');
      }
      if (formName !== null) {
        const dup = await db.query(
          'SELECT approval_form_id FROM approval_form WHERE form_name = :formName AND approval_form_id <> CAST(:approvalFormId AS bigint)',
          { formName, approvalFormId },
        );
        if (dup.length > 0) {
          throw new ApiError(409, 'APPROVAL_FORM_NAME_DUPLICATED', '동일한 양식명이 이미 존재합니다.');
        }
      }
      const rows = await db.query(
        `UPDATE approval_form SET
           form_name = COALESCE(CAST(:formName AS varchar), form_name),
           body_content = COALESCE(CAST(:bodyContent AS text), body_content),
           default_approval_rule = COALESCE(CAST(:defaultApprovalRule AS text), default_approval_rule),
           use_status = COALESCE(CAST(:useStatus AS varchar), use_status),
           updated_at = now()
         WHERE approval_form_id = CAST(:approvalFormId AS bigint)
         RETURNING ${FORM_COLUMNS}`,
        { formName, bodyContent, defaultApprovalRule, useStatus, approvalFormId },
      );
      return rows[0];
    });
  }

  @Delete('/approval-forms/:approvalFormId')
  async deleteApprovalForm(@Req() req: Request) {
    const user = currentUser(req);
    user.require('시스템 관리자');
    const approvalFormId = checkId(req.params['approvalFormId']);
    return transaction(async (db) => {
      const found = await db.query(
        'SELECT approval_form_id FROM approval_form WHERE approval_form_id = CAST(:approvalFormId AS bigint)',
        { approvalFormId },
      );
      if (found.length === 0) {
        throw new ApiError(404, 'APPROVAL_FORM_NOT_FOUND', '결재양식을 찾을 수 없습니다.');
      }
      // TODO: 기안에 사용된 양식이면 409 APPROVAL_FORM_IN_USE (기안 테이블이 입력에 없음)
      await db.execute(
        'DELETE FROM approval_form WHERE approval_form_id = CAST(:approvalFormId AS bigint)',
        { approvalFormId },
      );
      return {};
    });
  }
}

