import { useState } from 'react';
import {
  call, useData, Badge, Num, Filters, Band, DataTable, Pager, Drawer, Form, Field,
  TextInput, Select, ErrorText,
} from '../kit';
import type { PageProps, Row, Page, Column } from '../kit';

const USE_OPTIONS: [string, string][] = [['사용', '사용'], ['미사용', '미사용']];
const SIZE = 20;

type DrawerState =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'delete'; row: Row }
  | null;

export default function FnSfr029103X0ba06bPage({ role, notify }: PageProps) {
  const [useStatusInput, setUseStatusInput] = useState('');
  const [useStatus, setUseStatus] = useState('');
  const [page, setPage] = useState(0);
  const [drawer, setDrawer] = useState<DrawerState>(null);
  const [formName, setFormName] = useState('');
  const [formUse, setFormUse] = useState('사용');
  const [bodyContent, setBodyContent] = useState('');
  const [rule, setRule] = useState('');

  const { data, error, loading, reload } = useData<Page>(
    () => call<Page>('GET', '/approval-forms', role, undefined, { useStatus, page, size: SIZE }),
    [useStatus, page, role],
  );

  const openCreate = () => {
    setFormName('');
    setFormUse('사용');
    setBodyContent('');
    setRule('');
    setDrawer({ kind: 'create' });
  };

  const openEdit = (row: Row) => {
    setFormName(String(row.formName ?? ''));
    setFormUse(String(row.useStatus ?? '사용'));
    setBodyContent('');
    setRule('');
    setDrawer({ kind: 'edit', row });
  };

  const done = (text: string) => {
    notify(text);
    setDrawer(null);
    reload();
  };

  const submitCreate = async () => {
    if (formName.trim() === '') {
      throw new Error('결재양식명을 입력해 주세요.');
    }
    if (formUse === '') {
      throw new Error('사용 여부를 선택해 주세요.');
    }
    await call('POST', '/approval-forms', role, {
      formName,
      useStatus: formUse,
      bodyContent,
      defaultApprovalRule: rule,
    });
    done('결재양식을 등록했습니다.');
  };

  const submitEdit = async (row: Row) => {
    if (formName.trim() === '') {
      throw new Error('결재양식명을 입력해 주세요.');
    }
    const body: Row = { formName, useStatus: formUse };
    if (bodyContent !== '') {
      body.bodyContent = bodyContent;
    }
    if (rule !== '') {
      body.defaultApprovalRule = rule;
    }
    await call('PATCH', '/approval-forms/' + String(row.approvalFormId), role, body);
    done('결재양식을 수정했습니다.');
  };

  const submitDelete = async (row: Row) => {
    await call('DELETE', '/approval-forms/' + String(row.approvalFormId), role);
    done('결재양식을 삭제했습니다.');
  };

  const columns: Column[] = [
    { key: 'formName', label: '결재양식명' },
    { key: 'useStatus', label: '사용 여부', render: (r) => <Badge value={r.useStatus} /> },
    {
      key: 'actions',
      label: '처리',
      render: (r) => (
        <span>
          <button type="button" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
          <button type="button" onClick={(e) => { e.stopPropagation(); setDrawer({ kind: 'delete', row: r }); }}>삭제</button>
        </span>
      ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>전체 양식</h2>
        <Num value={data?.total ?? 0} />
      </section>
      <section className="box span-12">
        <h2>결재양식 목록</h2>
        <Filters
          onSearch={() => { setPage(0); setUseStatus(useStatusInput); }}
          onReset={() => { setUseStatusInput(''); setUseStatus(''); setPage(0); }}
        >
          <Field label="사용 여부">
            <Select value={useStatusInput} onChange={setUseStatusInput} options={USE_OPTIONS} placeholder="전체" />
          </Field>
        </Filters>
        <Band total={data?.total}>
          <button type="button" onClick={openCreate}>양식 추가</button>
        </Band>
        {error !== '' && <ErrorText text={error} />}
        <DataTable columns={columns} rows={data?.items ?? []} empty={loading ? '불러오는 중입니다.' : '결재양식이 없습니다.'} />
        <Pager page={page} size={SIZE} total={data?.total ?? 0} onPage={setPage} />
      </section>
      {drawer?.kind === 'create' && (
        <Drawer title="결재양식 등록" onClose={() => setDrawer(null)}>
          <Form onSubmit={submitCreate} submit="등록">
            <Field label="결재양식명" required>
              <TextInput value={formName} onChange={setFormName} />
            </Field>
            <Field label="사용 여부" required>
              <Select value={formUse} onChange={setFormUse} options={USE_OPTIONS} />
            </Field>
            <Field label="양식 본문 구성" wide>
              <TextInput value={bodyContent} onChange={setBodyContent} multiline />
            </Field>
            <Field label="기본 결재 규칙" wide>
              <TextInput value={rule} onChange={setRule} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {drawer?.kind === 'edit' && (
        <Drawer title="결재양식 수정" onClose={() => setDrawer(null)}>
          <Form onSubmit={() => submitEdit(drawer.row)} submit="수정">
            <Field label="결재양식명" required>
              <TextInput value={formName} onChange={setFormName} />
            </Field>
            <Field label="사용 여부">
              <Select value={formUse} onChange={setFormUse} options={USE_OPTIONS} />
            </Field>
            <Field label="양식 본문 구성" wide hint="비워 두면 기존 값을 유지합니다.">
              <TextInput value={bodyContent} onChange={setBodyContent} multiline />
            </Field>
            <Field label="기본 결재 규칙" wide hint="비워 두면 기존 값을 유지합니다.">
              <TextInput value={rule} onChange={setRule} multiline />
            </Field>
          </Form>
        </Drawer>
      )}
      {drawer?.kind === 'delete' && (
        <Drawer title="결재양식 삭제" onClose={() => setDrawer(null)}>
          <Form
            onSubmit={() => submitDelete(drawer.row)}
            submit="삭제"
            danger
            note={'"' + String(drawer.row.formName ?? '') + '" 양식을 삭제합니다. 기안에 사용된 양식은 삭제할 수 없으니 미사용으로 변경해 주세요.'}
          />
        </Drawer>
      )}
    </div>
  );
}
